def render_signature(sig: inspect.Signature, max_line_len: Optional[int]=
    None, prefix: str='') ->str:
    params = []
    for param in sig.parameters.values():
        rendered = render_parameter(param)
        params.append(rendered)

    if max_line_len is not None:
        # Check if we need to split parameters across multiple lines
        param_str = ", ".join(params)
        full_sig = "(" + param_str + ")"
        if len(full_sig) <= max_line_len:
            return full_sig

        # Split parameters across multiple lines
        lines = [prefix + "("]
        for i, param in enumerate(params):
            if i == 0:
                lines.append(prefix + "    " + param + ",")
            else:
                lines.append(prefix + "    " + param + ",")
        lines.append(prefix + ")")
        return "\n".join(lines)

    param_str = ", ".join(params)
    return "(" + param_str + ")"
